import{C as e,H as t,R as n,S as r,Z as i,v as a,w as o,x as s}from"./vue-BDYVXuuN.js";import{c}from"./app-m3La2wLh.js";var l=JSON.parse(`{"path":"/courses/zsb-english/l/14/","title":"第 14 课 · 状语从句 Adverbial Clauses | 备考·英语","lang":"zh-CN","frontmatter":{"title":"第 14 课 · 状语从句 Adverbial Clauses","createTime":"2026-09-09T22:39:43.000Z","permalink":"/courses/zsb-english/l/14/","banner":"/images/covers/zsb-english.png","description":"这是本课阅读版。即可在同一页阅读、作答与复习，学习记录保存在此设备。 / 01 · 语法专题 / 第十四课 语法专题 · 第十四课 对应教材上册 P127–P138 · 九大类状语从句全览：重点考 when/while/as、not...until、主将从现、where 辨析、as 让步倒装与 so...that/such...that。 考点地图 ·...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"第 14 课 · 状语从句 Adverbial Clauses\\",\\"image\\":[\\"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png\\"],\\"dateModified\\":\\"2026-10-07T13:23:39.000Z\\",\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://liuj66794-sys.github.io/blog/courses/zsb-english/l/14/"}],["meta",{"property":"og:site_name","content":"知序"}],["meta",{"property":"og:title","content":"第 14 课 · 状语从句 Adverbial Clauses"}],["meta",{"property":"og:description","content":"这是本课阅读版。即可在同一页阅读、作答与复习，学习记录保存在此设备。 / 01 · 语法专题 / 第十四课 语法专题 · 第十四课 对应教材上册 P127–P138 · 九大类状语从句全览：重点考 when/while/as、not...until、主将从现、where 辨析、as 让步倒装与 so...that/such...that。 考点地图 ·..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2026-10-07T13:23:39.000Z"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:image:src","content":"https://liuj66794-sys.github.io/blog/images/covers/zsb-english.png"}],["meta",{"name":"twitter:image:alt","content":"第 14 课 · 状语从句 Adverbial Clauses"}],["meta",{"property":"article:modified_time","content":"2026-10-07T13:23:39.000Z"}],["link",{"rel":"canonical","href":"https://liuj66794-sys.github.io/blog/courses/zsb-english/l/14/"}]]},"readingTime":{"minutes":73.08,"words":21923},"git":{"createdTime":1791379419000,"updatedTime":1791379419000,"contributors":[{"name":"38623","username":"","email":"386239680@qq.com","commits":1,"avatar":"https://gravatar.com/avatar/6a2940d3ff3182b82cb8a2c8dfebb295d647509713aef8bc86fb9e95a6767f99?d=retro"}]},"autoDesc":true,"filePathRelative":"courses/zsb-english/l/14.md","headers":[]}`),u={name:`14.md`};function d(c,l,u,d,f,p){let m=t(`VPLink`);return n(),s(`div`,null,[a(`blockquote`,null,[a(`p`,null,[l[1]||=e(`这是本课阅读版。`,-1),o(m,{href:`/blog/lessons/zsb-english/lessons/0014-adverbial-clauses.html`},{default:i(()=>[...l[0]||=[a(`strong`,null,`打开互动课程`,-1)]]),_:1}),l[2]||=e(`即可在同一页阅读、作答与复习，学习记录保存在此设备。`,-1)])]),a(`p`,null,[o(m,{href:`/blog/lessons/zsb-english/lessons/course.html`},{default:i(()=>[...l[3]||=[e(`课程总览`,-1)]]),_:1}),l[4]||=e(` / 01 · 语法专题 / 第十四课`,-1)]),l[10]||=r(`<p>语法专题 · 第十四课</p><p>对应教材上册 P127–P138 · 九大类状语从句全览：重点考 when/while/as、not...until、主将从现、where 辨析、as 让步倒装与 so...that/such...that。</p><div class="hint-container info"><p class="hint-container-title">考点地图 · 点击跳转</p><ol><li><a href="#pt-1"><strong>时间</strong>：when/while/as、一…就…、until、since、主将从现</a></li><li><a href="#pt-2"><strong>地点</strong>：where/wherever（与定语从句辨析）</a></li><li><a href="#pt-3"><strong>原因</strong>：because/since/now that/in that 等</a></li><li><a href="#pt-4"><strong>条件</strong>：if/unless/as long as/in case/on condition that 等</a></li><li><a href="#pt-5"><strong>让步</strong>：though/although、as 倒装、no matter = 疑问词-ever</a></li><li><a href="#pt-6"><strong>目的与结果</strong>：so that/in order that；so...that/such...that</a></li><li><a href="#pt-7"><strong>方式</strong>：as、(just) as...so...、as if/as though</a></li><li><a href="#pt-8"><strong>比较</strong>：as...as、比较级 + than、the more..., the more...</a></li></ol></div><h2 id="什么是状语从句" tabindex="-1"><a class="header-anchor" href="#什么是状语从句"><span>什么是状语从句</span></a></h2><p><strong>副词</strong>在句中表示行为或状态特征，主要充当状语，修饰动词、形容词、其他副词、介词短语或全句，表示时间、地点、程度、方式等概念。<strong>状语从句</strong>就是由一个从句来担任状语，可修饰谓语（或其他动词）、形容词、副词或整个句子。共九类：时间、地点、原因、条件、让步、目的、结果、方式、比较。</p><h2 id="第一类-·-时间状语从句" tabindex="-1"><a class="header-anchor" href="#第一类-·-时间状语从句"><span>第一类 · 时间状语从句</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第一类 · 时间状语从句</p><ul><li><strong>目标</strong>：解决“空里填哪个时间连词”：先用动作长短分清 when / while / as，再认“一……就……”三件套、not…until 与主将从现。</li><li><strong>建议用时</strong>：15 分钟</li><li><strong>知识点</strong>：<code>状语从句概说与九类从属连词</code> <code>时间状语从句连词（when / while / as）</code> <code>“一……就……”结构（hardly…when / no sooner…than）</code> <code>until / till 与 not…until…</code> <code>since 的时态搭配</code> <code>主将从现</code></li></ul></div><h3 id="第一类-·-时间状语从句-·-小步学" tabindex="-1"><a class="header-anchor" href="#第一类-·-时间状语从句-·-小步学"><span>第一类 · 时间状语从句 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>状语从句：补充什么时候、为什么、什么条件</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>when 是“点”，while 是“段”，as 是“一起变”</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>一……就……三件套：hardly…when、no sooner…than、as soon as</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>until 前是延续动作，not…until 前是瞬间动作</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>主将从现：从句里从不出现 will</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：先说清 when / while / as 的分工，再背出“一……就……”的两组固定搭配，最后用主句动词的延续与否解释 until 和 not…until 的区别。</p><div class="hint-container tip"><p class="hint-container-title">when 是“点”，while 是“段”，as 是“一起变”</p><p><strong>句意</strong>：I was walking in the street when suddenly someone patted me on the back. 意思是“我正在街上走着，这时突然有人拍了拍我的背”。</p><p><strong>拆解</strong></p><ul><li>I was walking in the street 是主句：过去进行时，表示一段正在持续的背景动作</li><li>when suddenly someone patted me on the back 是从句：patted 是短暂动作，插进那段持续的背景里，所以用 when</li><li>while 的典型场景是两段同时进行：While I was doing my homework, my mother was cooking in the kitchen.</li><li>as 强调伴随、随着：As time goes by, he has changed a lot.</li></ul><p><strong>语法</strong>：时间状语从句说明主句动作发生的时间，常见引导词 when、while、as、before、after、since、until、as soon as。when 接短暂或持续动作，还能进 be doing...when...、be about to do...when... 这类“这时突然”结构；while 多接持续动作或进行时；as 强调伴随与同步变化。</p><p>正例：I was walking in the street when suddenly someone patted me on the back.（从句短暂、主句持续）；While I was doing my homework, my mother was cooking in the kitchen.（两段同时）；As time goes by, he has changed a lot.（随着） 反例：She was watching TV while I came in. ×（came in 是瞬间动作，while 要求从句动作持续）；I was about to leave while the telephone rang. ×（be about to do...when... 是固定搭配，不能换 while） 适用边界：when 最宽：短暂动作、持续动作都能接；while 只认持续动作或进行时；as 强调两个动作同步发展。拿不准时先问一句：从句这个动作是“点”还是“段”。</p><p><strong>口诀</strong>：when 点点、点时都行；while 只认段；as 一起变 —— 把动作想成一条线上的点与段：突然发生的是点，用 when；两段并行用 while；两个动作一起往同一方向变化，用 as。</p></div><div class="hint-container tip"><p class="hint-container-title">一……就……三件套：hardly…when、no sooner…than、as soon as</p><p><strong>句意</strong>：Hardly had I arrived home when it began to rain. 意思是“我一到家，就开始下雨了”。</p><p><strong>拆解</strong></p><ul><li>Hardly 是否定副词、放在句首，所以主句部分倒装：had I arrived home</li><li>从句用一般过去时 began，主句用过去完成时 had arrived —— 两个动作有先后</li><li>no sooner…than 同理，但配对词是 than：No sooner had she gone to bed than the phone rang.</li><li>as soon as 最省事、不用倒装：She called me as soon as she arrived at the airport.</li></ul><p><strong>语法</strong>：表示“一……就……”有三种常见句式：hardly/scarcely had + 主语 + done + when + 主语 + did；no sooner had + 主语 + done + than + 主语 + did；as soon as + 一般现在时/一般过去时。“刚发生”的那一半用过去完成时，后一半用一般过去时。</p><ol><li>先发生的一半用过去完成时：had done</li><li>紧接着发生的一半用一般过去时：did</li></ol><p>正例：Hardly had I arrived home when it began to rain.；No sooner had she gone to bed than the phone rang.；She called me as soon as she arrived at the airport. 反例：Hardly had I arrived home than it began to rain. ×（hardly/scarcely 配 when）；No sooner had she gone to bed when the phone rang. ×（no sooner 配 than） 适用边界：配对词是死的：hardly/scarcely—when，no sooner—than。倒装只发生在把 hardly / no sooner 提到句首时；写成 I had hardly arrived home when… 就不倒装。</p><p><strong>口诀</strong>：hardly 配 when，no sooner 配 than，as soon as 不管倒装 —— 记住配对词，再记住只有否定副词置首才倒装，两条一合就不会写错。</p></div><div class="hint-container tip"><p class="hint-container-title">until 前是延续动作，not…until 前是瞬间动作</p><p><strong>句意</strong>：We waited until he came. 意思是“我们一直等到他来”；I didn&#39;t leave until he arrived. 意思是“直到他来，我才离开”。</p><p><strong>拆解</strong></p><ul><li>We waited until he came：wait 是延续性动作，一直延续到 he came 才停止，译“直到……为止”</li><li>I didn&#39;t leave until he arrived：leave 是瞬间动作，不可能一直“离开”到他来，所以要否定，动作到那时才开始，译“直到……才”</li><li>till 多用于口语或非正式语境，不能放在句首</li></ul><p><strong>语法</strong>：until/till 表“直到……为止”，主句谓语要用延续性动词；not...until... 表“直到……才”，主句谓语通常是非延续性动词，用否定式。</p><p>正例：We waited until/till he came.（延续性动词用肯定）；I didn&#39;t leave until he arrived.（非延续性动词用否定）；He didn&#39;t go to bed until he finished his homework. 反例：I left until he came. ×（left 是瞬间动词，不能与肯定式 until 连用表延续）；Till he came, we waited. ×（till 不能置于句首） 适用边界：判断的抓手是主句动词：能“一直做下去”的（wait、stay、work、keep）用肯定式；做一下就结束的（leave、go to bed、finish、start）必须先否定，才译得出“直到……才”。</p><p><strong>口诀</strong>：延续用肯定，瞬间要否定 —— 动词本身能不能延续，决定了用 until 还是 not...until，不靠语感猜。</p></div><div class="hint-container tip"><p class="hint-container-title">主将从现：从句里从不出现 will</p><p><strong>句意</strong>：I will call you when I arrive at the station. 意思是“我到车站时会给你打电话”。</p><p><strong>拆解</strong></p><ul><li>主句 I will call you 用一般将来时，说明事情发生在将来</li><li>从句 when I arrive at the station 说的虽然也是将来，却用一般现在时 arrive</li><li>条件从句同理：We will go to the park tomorrow if it doesn&#39;t rain.</li></ul><p><strong>语法</strong>：在时间状语从句和条件状语从句中，若主句用一般将来时，从句用一般现在时表示将来，这就是“主将从现”。</p><ol><li>主句 will call：事情在将来发生</li><li>从句 arrive：用一般现在时，站在“到达那一刻”说话，从句里不出现 will</li></ol><p>正例：I will call you when I arrive at the station.；We will go to the park tomorrow if it doesn&#39;t rain.；I&#39;ll tell him the news as soon as he comes back. 反例：I will call you when I will arrive at the station. ×（时间从句不出现 will）；If it won&#39;t rain tomorrow, we will go to the park. ×（条件从句也用一般现在时） 适用边界：这条规则只管时间状语从句和条件状语从句。宾语从句、定语从句该用将来时还得用：I don&#39;t know when he will arrive.（宾语从句）</p><p><strong>口诀</strong>：时间条件主将从现 —— 先看从句是不是“时间/条件”身份，是就把 will 收起来；是宾语从句就不受限制。</p></div><p>说明主句动作发生的时间，常见引导词：<strong>when、while、as、before、after、since、until、as soon as</strong> 等。</p><h3 id="_1-when、while-与-as" tabindex="-1"><a class="header-anchor" href="#_1-when、while-与-as"><span>1. when、while 与 as</span></a></h3><table><thead><tr><th>连词</th><th>含义</th><th>用法</th><th>例句</th></tr></thead><tbody><tr><td><strong>when</strong></td><td>在……时候；这时突然</td><td>① 从句为短暂动作、主句为持续动作；② 主从句均为短暂动作；③ 用于 <strong>be doing...when...</strong>、<strong>be about to do...when...</strong> 等结构</td><td>I was walking in the street <strong>when</strong> suddenly someone patted me on the back.（我正在街上走，这时突然有人拍了拍我的背。）</td></tr><tr><td><strong>while</strong></td><td>在……期间；与……同时</td><td>① 多与进行时搭配；② 可对比两种情况</td><td><strong>While</strong> I was doing my homework, my mother was cooking in the kitchen.（我做作业时，妈妈正在厨房做饭。）</td></tr><tr><td><strong>as</strong></td><td>一边……一边……；随着</td><td>强调伴随；主从句动作同时发展变化；从句动作可短暂也可持续</td><td><strong>As</strong> time goes by, he has changed a lot.（随着时间流逝，他改变了许多。）</td></tr></tbody></table><h3 id="_2-表示-一-就" tabindex="-1"><a class="header-anchor" href="#_2-表示-一-就"><span>2. 表示“一……就……&quot;</span></a></h3><ol><li><strong>hardly/scarcely had + 主语 + done + when + 主语 + did</strong>：<strong>Hardly had I arrived home when</strong> it began to rain.（我一到家就开始下雨了。）</li><li><strong>no sooner had + 主语 + done + than + 主语 + did</strong>：<strong>No sooner had she gone to bed than</strong> the phone rang.（她一上床，电话就响了。）</li><li><strong>as soon as</strong>：She called me <strong>as soon as</strong> she arrived at the airport.（她一到机场就给我打了电话。）</li></ol><h3 id="_3-until-till" tabindex="-1"><a class="header-anchor" href="#_3-until-till"><span>3. until / till</span></a></h3><table><thead><tr><th>句型</th><th>规则</th><th>例句</th></tr></thead><tbody><tr><td><strong>肯定句</strong></td><td>主句谓语为<strong>延续性动词</strong>，动作一直延续到某时才停止，译为&quot;直到……为止&quot;</td><td>We waited <strong>until/till</strong> he came.（我们一直等到他来。）</td></tr><tr><td><strong>否定句 not...until...</strong></td><td>主句谓语为<strong>非延续性动词</strong>，动作到某时才开始，译为&quot;直到……才&quot;</td><td>I <strong>didn&#39;t leave until</strong> he arrived.（直到他来，我才离开。）</td></tr></tbody></table><div class="hint-container caution"><p class="hint-container-title">易错</p><p>易错<strong>till 多用于口语或非正式语境，不能置于句首。</strong></p></div><h3 id="_4-since" tabindex="-1"><a class="header-anchor" href="#_4-since"><span>4. since</span></a></h3><p>since 表示&quot;自从……&quot;。时态通常遵循：<strong>从句用一般过去时，主句用现在完成时或过去完成时</strong>。</p><p>I <strong>have lived</strong> here <strong>since I was</strong> a child.（我从小就住在这里。） He said he <strong>had worked</strong> in that factory <strong>since he graduated</strong> from school.（他说自己毕业后一直在那家工厂工作。）</p><h3 id="_5-其他时间连词" tabindex="-1"><a class="header-anchor" href="#_5-其他时间连词"><span>5. 其他时间连词</span></a></h3><p><strong>the moment / the minute / the instant</strong>（一……就……）、<strong>the day</strong>（这天；那天）、<strong>each time</strong>（每次）、<strong>the first time</strong>（第一次）、<strong>once</strong>（一旦；一……就……）。</p><h3 id="_6-主将从现" tabindex="-1"><a class="header-anchor" href="#_6-主将从现"><span>6. “主将从现&quot;</span></a></h3><p>在<strong>时间状语从句和条件状语从句</strong>中，若主句用一般将来时，从句用一般现在时表示将来。</p><p>I <strong>will call</strong> you when I <strong>arrive</strong> at the station.（我到车站时会给你打电话。） We <strong>will go</strong> to the park tomorrow if it <strong>doesn&#39;t rain</strong>.（如果明天不下雨，我们就去公园。）</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>口诀<strong>时间条件主将从现。</strong></p></div><h2 id="第二类-·-地点状语从句" tabindex="-1"><a class="header-anchor" href="#第二类-·-地点状语从句"><span>第二类 · 地点状语从句</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第二类 · 地点状语从句</p><ul><li><strong>目标</strong>：解决“where 到底是不是从句连词”，并顺手把第三类原因连词按语气强弱排成一条线——本组把第二类地点与第三类原因合为一节（两类都短、都靠选连词得分）。</li><li><strong>建议用时</strong>：11 分钟</li><li><strong>知识点</strong>：<code>地点状语从句 where / wherever</code> <code>原因状语从句连词（because / since / as / for / now that）</code></li></ul></div><h3 id="第二类-·-地点状语从句-·-小步学" tabindex="-1"><a class="header-anchor" href="#第二类-·-地点状语从句-·-小步学"><span>第二类 · 地点状语从句 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>状语从句：补充什么时候、为什么、什么条件</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>有先行词是定语从句，没先行词是地点状语从句</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>原因连词排成一条线：because 最强、for 最松</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：用一句话说清地点状语从句与定语从句的判别线，再按语气从强到弱排出原因连词并各造一句。</p><div class="hint-container tip"><p class="hint-container-title">有先行词是定语从句，没先行词是地点状语从句</p><p><strong>句意</strong>：Please make marks where you have questions. 意思是“请在有疑问的地方做标记”；Please make marks at the places where you have questions. 意思是“请在你存有疑问的那些地方做标记”。</p><p><strong>拆解</strong></p><ul><li>第一句 where 前面没有任何表示地点的名词，where 直接说明 make marks 这个动作发生在哪儿 → 地点状语从句</li><li>第二句 where 前面有先行词 the places，where 在从句里作地点状语、指代那些地方 → 定语从句</li><li>两句意思几乎一样，差别就在加不加 at the places</li></ul><p><strong>语法</strong>：地点状语从句通常由 where、wherever 引导：where 前没有地点先行词，where 是从属连词，直接修饰主句谓语；where 前有地点先行词时，它是关系副词，属定语从句。</p><p>正例：Please make marks where you have questions.（地点状语从句）；Please make marks at the places where you have questions.（定语从句）；You are free to go wherever you like.（无论哪里） 反例：Medicine should not be kept which the children can easily reach. ×（which 需要有先行词，也不能在从句中作地点状语）；You should leave things there you can find them again. ×（there 是副词，不能引导从句） 适用边界：不要只凭“有没有先行词”一刀切：名词性从句里的 where 也没有先行词（This is where we first met.）。区分靠结构——从句占了主句的成分就是名词性从句，只作状语才是状语从句。</p><p><strong>口诀</strong>：有先行词是定语，没先行词是状语 —— 先看空格前有没有表示地点的名词；没有，就轮到“从句在句子里当什么成分”来裁决。</p></div><div class="hint-container tip"><p class="hint-container-title">原因连词排成一条线：because 最强、for 最松</p><p><strong>句意</strong>：I didn&#39;t go to the party last night because I was very tired. 意思是“我昨晚没去参加聚会，因为我很累”；The day must be breaking, for the birds have begun singing. 意思是“天一定快亮了，因为鸟儿已经开始叫了”。</p><p><strong>拆解</strong></p><ul><li>because 直接回答 why、语气最强：because I was very tired 就是没去的直接原因</li><li>for 是并列连词，说的是“推断的根据”：由鸟叫推出天快亮，前面还有 must be 表推测，正配 for</li><li>since、as、now that 译“既然”，把原因当成已知前提：Now that we have finished the project, why don&#39;t you take a week off?</li><li>in that、seeing that、considering that 是书面色彩更浓的“因为、鉴于”</li></ul><p><strong>语法</strong>：原因状语从句的常见引导词：because（直接原因、回答 why）；since、as、now that（既然、已知理由）；for（并列连词，补充说明推断理由，不能置于句首）；in that、seeing that、considering that（因为、鉴于）。</p><p>正例：I didn&#39;t go to the party last night because I was very tired.；Now that we have finished the project, why don&#39;t you take a week off?；The day must be breaking, for the birds have begun singing. 反例：For he was ill, he didn&#39;t come to class. ×（for 是并列连词，不能置于句首）；Now that I was very tired, I didn&#39;t go to the party. ×（now that 用于双方已知的前提，个人一时的累不该用它） 适用边界：只有 because 能回答 Why…? 也能被 only 强调（only because）；for 永远跟在后面、前面加逗号，且只能补充推断理由，不能当直接原因。</p><p><strong>口诀</strong>：why 用 because，推断用 for，既然 since / as / now that —— 先问“这句话是在回答为什么，还是由现象推结论”：回答为什么用 because，推结论用 for。</p></div><p>通常由 <strong>where、wherever</strong> 引导。</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>where 引导状语从句与定语从句的区别 <strong>地点状语从句</strong>：where 前没有表示地点的先行词，直接修饰主句谓语，where 是从属连词：Please make marks <strong>where</strong> you have questions.（请在有疑问的地方做标记。）</p><p><strong>定语从句</strong>：where 前有地点先行词，where 在从句中作地点状语，是关系副词：Please make marks at the places <strong>where</strong> you have questions.（请在你有疑问的那些地方做标记。）</p></div><h2 id="第三类-·-原因状语从句" tabindex="-1"><a class="header-anchor" href="#第三类-·-原因状语从句"><span>第三类 · 原因状语从句</span></a></h2><p>常见引导词：<strong>because、since</strong>（因为；既然）、<strong>as、for、now that</strong>（既然）、<strong>in that</strong>（因为；由于）、<strong>seeing that</strong>（鉴于）、<strong>considering that</strong>（鉴于）等。</p><h2 id="第四类-·-条件状语从句" tabindex="-1"><a class="header-anchor" href="#第四类-·-条件状语从句"><span>第四类 · 条件状语从句</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第四类 · 条件状语从句</p><ul><li><strong>目标</strong>：解决“填 if 还是 unless、还是 as long as”：把条件连词分成正面条件、否定条件、防备条件三格，并检查从句里有没有混进 will。</li><li><strong>建议用时</strong>：12 分钟</li><li><strong>知识点</strong>：<code>条件状语从句连词（if / unless / as long as…）</code></li></ul></div><h3 id="第四类-·-条件状语从句-·-小步学" tabindex="-1"><a class="header-anchor" href="#第四类-·-条件状语从句-·-小步学"><span>第四类 · 条件状语从句 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>状语从句：补充什么时候、为什么、什么条件</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>条件连词三格：正面 if、否定 unless、防备 in case</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>条件从句也守主将从现，但要看 if 的身份</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：把条件连词分三格各举一例，并说出 unless 与 if...not 的换算方式。</p><div class="hint-container tip"><p class="hint-container-title">条件连词三格：正面 if、否定 unless、防备 in case</p><p><strong>句意</strong>：You will succeed as long as you don&#39;t lose heart. 意思是“只要你不灰心，就会成功”；Let&#39;s go out for a walk unless you are too tired. 意思是“除非你太累，否则我们出去散散步吧”。</p><p><strong>拆解</strong></p><ul><li>正面条件：if（如果）、as/so long as（只要）、once（一旦）、on condition that（条件是）、provided/providing that（倘若）、supposing that（假如）</li><li>否定条件：unless = if...not，“除非……否则”，主句多是否定的结果</li><li>防备条件：in case（万一、以防），常表示对可能发生的坏情况的防备</li></ul><p><strong>语法</strong>：条件状语从句由 if、unless、as/so long as、in case、once、on condition that、provided that、supposing that 等引导，说明主句动作成立的条件。</p><p>正例：You will succeed as long as you don&#39;t lose heart.；Let&#39;s go out for a walk unless you are too tired.；In case there is a fire, what should we do first?；You can join us in this activity on condition that you follow these rules strictly. 反例：It is known to all that if you exercise regularly, you won&#39;t keep good health. ×（if 后是正面条件，却配了否定结果，该用 unless）；Unless the government will agree to give extra money, the theater will close. ×（条件从句里不出现 will） 适用边界：unless 后面跟的是“唯一的例外条件”，主句才是否定结果；如果条件本身已经是否定式（if you don&#39;t…），就不能再套 unless，否则成了双重否定。</p><p><strong>口诀</strong>：正面 if，否定 unless，防备 in case —— 先看主句是肯定结果还是否定结果：否定结果八成配 unless；再问是不是“以防万一”，是就用 in case。</p></div><div class="hint-container tip"><p class="hint-container-title">条件从句也守主将从现，但要看 if 的身份</p><p><strong>句意</strong>：You need to practise talking to each other if you want to speak fluent English. 意思是“如果你想说出流利的英语，就需要互相练习对话”。</p><p><strong>拆解</strong></p><ul><li>if you want to speak fluent English 是条件，说明主句结论成立的前提</li><li>从句用一般现在时 want；主句 You need to practise… 是结论</li><li>若主句换成将来时，从句照样不出现 will：If it doesn&#39;t rain tomorrow, we will go to the park.</li></ul><p><strong>语法</strong>：条件状语从句与时间状语从句一样遵守主将从现；但 if 引导宾语从句时表示“是否”，不受这条限制（I don&#39;t know if he will come.）。</p><ol><li>从句：用一般现在时表将来</li><li>主句：用 will + 动词原形</li></ol><p>正例：If it doesn&#39;t rain tomorrow, we will go to the park.；I don&#39;t know if he will come.（宾语从句，可以用 will） 反例：If it will not rain tomorrow, we will go to the park. ×（条件从句不出现 will）；I don&#39;t know if he comes. ×（这里的 if 是“是否”，该说 will come） 适用边界：先判断 if 从句的身份：能翻译成“如果”的是条件状语从句，翻译成“是否”的是宾语从句。身份一换，规则就换。</p><p><strong>口诀</strong>：if 当“如果”不收 will，if 当“是否”照常用 —— 判断顺序是先翻译再套规则，不要看见 if 就把 will 划掉。</p></div><p>常见引导词：<strong>if、unless</strong>（除非）、<strong>as/so long as</strong>（只要）、<strong>in case</strong>（万一）、<strong>once</strong>（一旦）、<strong>on condition that</strong>（条件是）、<strong>provided/providing (that)</strong>（倘若）、<strong>supposing (that)</strong>（假如）等。</p><p><strong>Let&#39;s go out for a walk unless you are too tired.</strong>（除非你太累了，否则我们出去散步吧。） <strong>If you are not too tired, let&#39;s go out for a walk.</strong>（如果你不太累，我们就出去散步吧。） <strong>You will succeed as long as you don&#39;t lose heart.</strong>（只要你不灰心，就会成功。） <strong>In case there is a fire, what should we do first?</strong>（万一发生火灾，我们首先该做什么？）</p><h2 id="第五类-·-让步状语从句" tabindex="-1"><a class="header-anchor" href="#第五类-·-让步状语从句"><span>第五类 · 让步状语从句</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第五类 · 让步状语从句</p><ul><li><strong>目标</strong>：解决“虽然、即使、无论”怎么说：记住 though/although 不与 but 连用、as 让步必须倒装、no matter 与疑问词-ever 的换算与分工。</li><li><strong>建议用时</strong>：13 分钟</li><li><strong>知识点</strong>：<code>让步状语从句（though / although / even if / no matter…）</code> <code>as / though 让步倒装</code></li></ul></div><h3 id="第五类-·-让步状语从句-·-小步学" tabindex="-1"><a class="header-anchor" href="#第五类-·-让步状语从句-·-小步学"><span>第五类 · 让步状语从句 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>状语从句：补充什么时候、为什么、什么条件</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>though / although 不与 but 连用，但可与 yet 连用</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>让步 as 必倒装，名词提前去冠词</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>no matter what = whatever，no matter how = however</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：说出让步句的三条硬规则：不与 but 连用、as 必倒装、no matter 后接陈述语序，并各举一例。</p><div class="hint-container tip"><p class="hint-container-title">though / although 不与 but 连用，但可与 yet 连用</p><p><strong>句意</strong>：Although it&#39;s raining, they are still working in the field. 意思是“尽管下着雨，他们仍在田里劳动”；Though the sore be healed, yet a scar may remain. 意思是“伤口虽已愈合，疤痕仍可能留下”。</p><p><strong>拆解</strong></p><ul><li>Although it&#39;s raining 在句首引出让步，主句 they are still working in the field 是与预期相反的结果</li><li>Though the sore be healed 后面接了 yet a scar may remain：though 可以与 yet 连用</li><li>两句里都没有 but —— although / though 与 but 只能留一个</li></ul><p><strong>语法</strong>：让步状语从句表示“虽然、尽管、即使”，常见引导词 though、although、even if（即使）、even though（尽管）、whether...or...（不管……还是……）、no matter + 疑问词。though/although 不能与 but 连用，though 可与 yet 连用。</p><p>正例：Although it&#39;s raining, they are still working in the field.；Though the sore be healed, yet a scar may remain.；Even if he is poor, she loves him. 反例：Although it&#39;s raining, but they are still working. ×（although 与 but 二选一）；Whether you believe it or not, but it&#39;s true. ×（不要额外加 but） 适用边界：让步句的标志是“前后与预期相反”。如果前后是同向的因果（累→没去），那是原因从句，用 because 而不该用 though。</p><p><strong>口诀</strong>：有 though 无 but，可留 yet —— 中文“虽然……但是……”要分开译：英文里 though/although 和 but 各占一头，同时出现就重复了。</p></div><div class="hint-container tip"><p class="hint-container-title">让步 as 必倒装，名词提前去冠词</p><p><strong>句意</strong>：Child as he was, he knew what was the right thing to do. 意思是“他虽然还是个孩子，却知道该做什么才是对的”。</p><p><strong>拆解</strong></p><ul><li>正常语序是 He was a child；改成 can 让步句要把表语 child 提到 as 前面</li><li>名词表语提到句首时要省掉冠词 a：Child as he was，而不是 A child as he was</li><li>状语提前：Much as I like the book, I don&#39;t have enough money to buy it.</li><li>动词原形提前：Try as he might, he couldn&#39;t solve the problem.</li></ul><p><strong>语法</strong>：as 表“虽然、尽管”引导让步从句时必须倒装，结构为“表语/状语/动词原形 + as + 主语 + 谓语”；单数可数名词作表语提前时省略冠词。though 可以这样倒装，也可以不倒装；although 永远不倒装。</p><p>正例：Child as/though he was, he knew what was the right thing to do.；Much as/though I like the book, I don&#39;t have enough money to buy it.；Try as/though he might, he couldn&#39;t solve the problem. 反例：As he was a child, he knew what was the right thing to do. ×（as 表让步必须倒装，这样写会被读成“当他是孩子的时候”）；A child as he was, … ×（名词提前时要去掉冠词） 适用边界：这条倒装只属于 as 和 though。看到句首的 as 要先看语序：倒装了才表“虽然”，不倒装则表“因为/当……时/正如”。</p><p><strong>口诀</strong>：让步 as 必倒装，名词提前去冠词 —— 先确认是让步（前后相反）→ 再确认语序（倒装）→ 最后检查名词前的冠词有没有删掉。</p></div><div class="hint-container tip"><p class="hint-container-title">no matter what = whatever，no matter how = however</p><p><strong>句意</strong>：No matter how much it costs, we have to get that car fixed. 意思是“不管花多少钱，我们都得把那辆车修好”。</p><p><strong>拆解</strong></p><ul><li>no matter how much 后面的从句用陈述语序：it costs，不倒装</li><li>no matter what = whatever，后面接名词：Whatever difficulty they may come across…</li><li>no matter how = however，后面接形容词或副词：However great the difficulty is…</li><li>no matter + 疑问词只能引导让步从句；疑问词 + -ever 还能引导名词性从句</li></ul><p><strong>语法</strong>：no matter + 疑问词 = 疑问词 + -ever：no matter what = whatever，no matter how = however，no matter where = wherever，no matter which = whichever。从句一律用陈述语序。</p><p>正例：No matter what you say, it is of no use now. = Whatever you say, it is of no use now.；Whatever difficulty they may come across, they&#39;ll help one another to overcome it.；However great it is, you can overcome the difficulty. 反例：No matter how much does it cost, we have to get the car fixed. ×（no matter 从句用陈述语序，不倒装）；However difficulty they may come across, … ×（however 只能修饰形容词或副词，修饰名词要用 whatever） 适用边界：先找出从句里的核心词：名词 → whatever / no matter what；形容词或副词 → however / no matter how。选错词根，语序再对也不得分。</p><p><strong>口诀</strong>：名词 whatever，形副 however —— whatever 是个“名词袋子”，however 是个“程度旋钮”，先看从句缺的是名词还是程度。</p></div><h3 id="_1-though-although" tabindex="-1"><a class="header-anchor" href="#_1-though-although"><span>1. though / although</span></a></h3><p>二者引导让步状语从句时，<strong>不能与 but 连用</strong>；但 <strong>though 可与 yet 连用</strong>。</p><p><strong>Though the sore be healed, yet a scar may remain.</strong>（伤口虽愈合，疤痕仍可能留下。） <strong>Although it&#39;s raining, they are still working in the field.</strong>（尽管下着雨，他们仍在田里劳动。）</p><h3 id="_2-as-though-的让步倒装" tabindex="-1"><a class="header-anchor" href="#_2-as-though-的让步倒装"><span>2. as / though 的让步倒装</span></a></h3><p>as 表示&quot;虽然、尽管&quot;时，必须把<strong>表语、状语或动词原形</strong>提前；though 可倒装也可不倒装。<strong>名词表语提前时要去掉冠词</strong>。</p><table><thead><tr><th>提前成分</th><th>例句</th></tr></thead><tbody><tr><td>表语提前</td><td><strong>Child as/though he was</strong>, he knew what was the right thing to do.（他虽然还是个孩子，却知道该做什么。）</td></tr><tr><td>状语提前</td><td><strong>Much as/though I like the book</strong>, I don&#39;t have enough money to buy it.（我虽然很喜欢这本书，却没有足够的钱买它。）</td></tr><tr><td>动词原形提前</td><td><strong>Try as/though he might</strong>, he couldn&#39;t solve the problem.（尽管他努力尝试，仍解决不了这个问题。）</td></tr></tbody></table><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>口诀<strong>让步 as 必倒装，名词提前去冠词。</strong></p></div><h3 id="_3-其他让步结构" tabindex="-1"><a class="header-anchor" href="#_3-其他让步结构"><span>3. 其他让步结构</span></a></h3><ol><li><strong>even if / even though</strong>（即使；尽管）：<strong>Even if he is poor, she loves him.</strong> / <strong>Even though he is poor, she loves him.</strong>（即使/尽管他贫穷，她仍爱他。）</li><li><strong>whether...or...</strong>（不管……还是……）：<strong>Whether you believe it or not, it&#39;s true.</strong>（不管你信不信，这都是真的。）</li><li><strong>no matter + 疑问词 = 疑问词 + -ever</strong>：no matter what = whatever；no matter how = however；no matter where = wherever；no matter which = whichever。<strong>No matter what you say, it is of no use now.</strong> = <strong>Whatever you say, it is of no use now.</strong>（无论你说什么，现在都没有用了。）</li></ol><div class="hint-container caution"><p class="hint-container-title">易错</p><p>易错<strong>no matter + 疑问词只能引导让步状语从句；疑问词 + -ever 既能引导名词性从句，也能引导让步状语从句。</strong></p></div><h2 id="第六类-·-目的状语从句与结果状语从句" tabindex="-1"><a class="header-anchor" href="#第六类-·-目的状语从句与结果状语从句"><span>第六类 · 目的状语从句与结果状语从句</span></a></h2><div class="hint-container info"><p class="hint-container-title">本节指引 · 第六类 · 目的状语从句与结果状语从句</p><ul><li><strong>目标</strong>：解决 so that 与 so/such…that 的分工，并把本课没有配套练习的第七类方式、第八类比较收束成一句口诀，顺带挂到第 17 课的 that/those 替代。</li><li><strong>建议用时</strong>：12 分钟</li><li><strong>知识点</strong>：<code>目的状语从句与结果状语从句（so that / so…that / such…that）</code> <code>方式状语从句（as / as if / as though）</code> <code>比较状语从句（as…as / than / the more…the more…）</code></li></ul></div><h3 id="第六类-·-目的状语从句与结果状语从句-·-小步学" tabindex="-1"><a class="header-anchor" href="#第六类-·-目的状语从句与结果状语从句-·-小步学"><span>第六类 · 目的状语从句与结果状语从句 · 小步学</span></a></h3><p>先理解例子，再解释理由，最后独立练习。这里选取 4 道原课题；完整练习保留在下方原课内容。其余题目未计入本轮，存疑题不参与本轮自动判分。</p><p>打开本课交互版，可按以下步骤学习、保存作答并继续上次进度。下方保留完整原课讲义与解析。</p><details class="hint-container details"><summary>分步学习路线</summary><ol><li><strong>状语从句：补充什么时候、为什么、什么条件</strong>：先用自己的话说说：这节内容要帮你解决什么问题？</li><li><strong>目的从句：so that / in order that + 情态动词</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>先自己判断，再核对理由</strong></li><li><strong>结果从句：名前 such，形副 so；多多少少必用 so</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>方式与比较一句带过（第七、八类）</strong>：试着指出例子中的线索，再用一句话解释为什么这样表达。</li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li><li><strong>换一道，独立判断</strong></li></ol></details><p><strong>自己说一遍</strong>：用一句口诀说出 so 与 such 的分工，再各举一个目的从句、一个比较从句的例子。</p><div class="hint-container tip"><p class="hint-container-title">目的从句：so that / in order that + 情态动词</p><p><strong>句意</strong>：The teacher raised her voice so that the students in the back row could hear more clearly. 意思是“老师提高了声音，以便后排的学生能听得更清楚”。</p><p><strong>拆解</strong></p><ul><li>主句 The teacher raised her voice 是手段，从句 could hear more clearly 是目的</li><li>目的从句里常见 can、could、would 这类情态动词</li><li>I&#39;d like to arrive 20 minutes earlier so that I can have time for a cup of tea. 也是同一结构</li></ul><p><strong>语法</strong>：目的状语从句常由 so that（以便）、in order that、in case（以备、以防）引导，从句中通常使用情态动词；in order that 更正式，其从句可以提到主句之前。</p><p>正例：The teacher raised her voice so that/in order that the students in the back row could hear more clearly.；I hurried so that I wouldn&#39;t be late for class.；Peter had to work hard day and night in order that he could earn more. 反例：I hurried since I wouldn&#39;t be late for class. ×（since 表原因，会把目的说成原因，方向反了）；I&#39;d like to arrive earlier in order to I can have time for a cup of tea. ×（in order to 后接动词原形，不能带主语和情态动词） 适用边界：so that 既能表目的也能表结果：从句里带 can/could/would 多为目的，单纯陈述事实的多为结果（He made such great progress that his parents were pleased.）。</p><p><strong>口诀</strong>：目的看情态，结果看事实 —— 先看从句里有没有情态动词；有，基本是目的从句。</p></div><div class="hint-container tip"><p class="hint-container-title">结果从句：名前 such，形副 so；多多少少必用 so</p><p><strong>句意</strong>：He is such a clever boy that he solves the problem quickly. 意思是“他是个如此聪明的男孩，很快就解决了这个问题”；The movie is so interesting that I want to watch it again. 意思是“这部电影如此有趣，我想再看一遍”。</p><p><strong>拆解</strong></p><ul><li>such a clever boy：such + a + 形容词 + 单数可数名词</li><li>so interesting：so + 形容词</li><li>progress、information 这类不可数名词不说 a：such great progress that…</li><li>多多少少必用 so：so many people、so much water、so few、so little（表“少”）；而 little 表“小”时用 such：such a little cat</li></ul><p><strong>语法</strong>：结果状语从句由 so...that、such...that 引导。so 后接形容词或副词，such 后接名词（可与形容词连用）；many/much/few/little 表示“多少”时用 so；little 表“小”用 such，表“少”用 so。</p><p>正例：He is such a clever boy that he solves the problem quickly.；The movie is so interesting that I want to watch it again.；There are so many people in the park that it&#39;s hard to walk.；He has so little patience that he gets angry easily.；It&#39;s such a little cat that it fits in my hand. 反例：He made so great progress that his parents were pleased. ×（progress 不可数，用 such great progress）；The film was such boring that I fell asleep. ×（boring 是形容词，用 so boring） 适用边界：先定位空格后紧跟的第一个词：形容词或副词 → so；名词或“形容词 + 名词” → such；many/much/few/little 表数量 → 一律 so。</p><p><strong>口诀</strong>：名前 such，形副 so；多多少少必用 so；little 表“小”用 such、表“少”用 so —— 把 so 想成只能抱形容词和副词，such 抱名词；再把 many/much/few/little 划归 so 这一边。</p></div><div class="hint-container tip"><p class="hint-container-title">方式与比较一句带过（第七、八类）</p><p><strong>句意</strong>：You must do as I told you. 意思是“你必须按我告诉你的去做”；Tom works as hard as Mary. 意思是“汤姆和玛丽工作一样努力”。</p><p><strong>拆解</strong></p><ul><li>as 表“正如”，引导方式从句：You must do as I told you.</li><li>as if / as though 表“仿佛”，与事实相反时用虚拟：They ignore these facts as if they never existed.</li><li>比较从句：同级用 as...as，不同级用比较级 + than，还有 the more..., the more...（越……越……）</li><li>比较结构里为避免重复，用 that/those 替代前面出现过的名词：The air here is fresher than that in the city. —— 这就是第 17 课的起点</li></ul><p><strong>语法</strong>：方式状语从句由 as、(just) as...so...、as if/as though 引导；比较状语从句由 as + adj./adv. + as、not as/so...as、比较级 + than、the more..., the more... 引导。as if 所述与事实相反时用虚拟语气。</p><p>正例：You must do as I told you.；Just as we sweep our rooms, so we should sweep backward ideas from our minds.；Tom works as hard as Mary.；The busier she is, the happier she feels. 反例：Tom works as hard like Mary. ×（同级比较用 as...as，不用 like）；The air here is fresher than it in the city. ×（替代不可数名词 air 要用 that，不能用 it） 适用边界：as if 后用不用虚拟，取决于所述是否与事实相反：与事实相反用虚拟（as if he had seen it before），可能为事实就用陈述（It looks as if the weather may pick up soon.）。</p><p><strong>口诀</strong>：方式看 as，比较看 as...as 与 than —— 两个 as 是一对（同级比较），一个 as 加 than 是另一回事；做题先找配对词。</p></div><h3 id="_1-目的状语从句" tabindex="-1"><a class="header-anchor" href="#_1-目的状语从句"><span>1. 目的状语从句</span></a></h3><p>常由 <strong>so that</strong>（以便）、<strong>in order that</strong>、<strong>in case</strong>（以备；以防）引导，从句中通常使用情态动词。</p><p>The teacher raised her voice <strong>so that/in order that</strong> the students in the back row could hear more clearly.（老师提高声音，以便后排学生听得更清楚。）</p><h3 id="_2-结果状语从句" tabindex="-1"><a class="header-anchor" href="#_2-结果状语从句"><span>2. 结果状语从句</span></a></h3><p>常由 <strong>so that、so...that...、such...that...</strong> 引导。so 后接<strong>形容词或副词</strong>，such 后接<strong>名词</strong>；so...that... 与 such...that... 在条件合适时可互换。</p><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>课件口诀<strong>名前 such，形副 so；that 从句跟在后。多多少少必用 so</strong>：many / much / few / little 表&quot;多少&quot;时用 so。<strong>特别注意 little</strong>：&quot;小&quot;用 such，&quot;少&quot;用 so。</p></div><p>He is <strong>such a clever boy that</strong> he solves the problem quickly.（他是个如此聪明的男孩，很快就解决了问题。） The movie is <strong>so interesting that</strong> I want to watch it again.（这部电影如此有趣，我想再看一遍。） There are <strong>so many people</strong> in the park that it&#39;s hard to walk.（公园里人如此多，走路都很困难。） It&#39;s <strong>such a little cat that</strong> it fits in my hand.（这只猫如此小，一只手就能托住。） He has <strong>so little patience that</strong> he gets angry easily.（他耐心如此少，很容易生气。）</p><h2 id="第七类-·-方式状语从句" tabindex="-1"><a class="header-anchor" href="#第七类-·-方式状语从句"><span>第七类 · 方式状语从句</span></a></h2><ol><li><strong>as</strong>（正如）：You must do <strong>as</strong> I told you.（你必须照我告诉你的去做。）</li><li><strong>(just) as...so...</strong>（就像……一样……），多用于正式文体：<strong>Just as we sweep our rooms, so we should sweep backward ideas from our minds.</strong>（正如我们清扫房间一样，我们也应清除头脑中的落后思想。）</li><li><strong>as if / as though</strong>：意义、用法相同。表示<strong>与事实相反</strong>时，从句谓语多用<strong>虚拟语气</strong>；表示事实或实现可能性较大时也可用<strong>陈述语气</strong>，译为&quot;仿佛……似的&quot;。They completely ignore these facts <strong>as if/as though they never existed</strong>.（他们完全忽略这些事实，仿佛它们从未存在过。） It looks <strong>as if the weather may pick up</strong> very soon.（看来天气可能很快好转。）</li></ol><h2 id="第八类-·-比较状语从句" tabindex="-1"><a class="header-anchor" href="#第八类-·-比较状语从句"><span>第八类 · 比较状语从句</span></a></h2><table><thead><tr><th>类型</th><th>结构</th><th>例句</th></tr></thead><tbody><tr><td>同级比较</td><td>as + adj./adv. + as（和……一样）</td><td>Tom works <strong>as hard as</strong> Mary.（汤姆和玛丽工作一样努力。）</td></tr><tr><td>同级比较</td><td>not as/so + adj./adv. + as（不如……）</td><td>The movie is <strong>not so exciting as</strong> I expected.（这部电影没有我预想的那么精彩。）</td></tr><tr><td>同级比较</td><td>倍数 + as + adj./adv. + as（是……的几倍）</td><td>I spent <strong>three times as much as</strong> you did, so I finally passed the exam.（我花的时间是你的三倍，所以最终通过了考试。）</td></tr><tr><td>不同级比较</td><td>adj./adv. 比较级 + than</td><td>The lesson is <strong>more difficult than</strong> I expected it to be.（这节课比我预想的更难。）</td></tr><tr><td>不同级比较</td><td>the more..., the more...（越……就越……）</td><td><strong>The busier she is, the happier she feels.</strong>（她越忙，越觉得快乐。）</td></tr><tr><td>不同级比较</td><td>more and more + 原级 / 比较级 + and + 比较级（越来越……）</td><td>It is getting <strong>more and more difficult</strong> to solve this problem.（解决这个问题正变得越来越困难。）</td></tr></tbody></table><h2 id="易错清单" tabindex="-1"><a class="header-anchor" href="#易错清单"><span>易错清单</span></a></h2><div class="hint-container caution"><p class="hint-container-title">易错</p><p>高频易错</p><ol><li><p><strong>主将从现</strong>只看状语从句：主句将来时，时间/条件从句用一般现在时</p></li><li><p>when 可接短暂动作，也可用于&quot;正在/正要……这时……&quot;；while 更常接持续动作或进行时</p></li><li><p>肯定句中 until 前通常是<strong>延续性动词</strong>；非延续性动词常用 <strong>not...until...</strong></p></li><li><p>where 前<strong>无</strong>地点先行词多为地点状语从句；<strong>有</strong>地点先行词多为定语从句</p></li><li><p>although/though 不与 but 连用；though 可与 yet 连用</p></li><li><p>as 引导让步从句<strong>必须倒装</strong>；名词表语提前时去冠词</p></li><li><p>so + 形/副 + that；such +（形容词）+ 名词 + that；many/much/few/little 表数量时用 so</p></li><li><p>as if/as though 表示与事实相反时常用虚拟语气，可能为事实时可用陈述语气</p></li></ol></div><h2 id="课堂练习" tabindex="-1"><a class="header-anchor" href="#课堂练习"><span>课堂练习</span></a></h2><p><strong>She was watching TV ____ I came in.</strong></p><ul><li>A. when</li><li>B. while</li><li>C. as</li><li>D. since</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（when）</strong> —— 从句动作 came in 短暂，主句 was watching 持续，用 when。（时间状语从句随堂练习）</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ 主句 was watching TV 是持续动作，从句 came in 是短暂动作，用 when 把“点”插进“段”里最自然。</li><li>B ❌ while 要求从句动作与主句同时持续（While I was doing my homework, my mother was cooking.），came in 是一下子完成的动作，不能“在……期间”。干扰点：把 while 当成 when 的同义词。</li><li>C ❌ as 强调伴随、随着（As time goes by…），两个动作同步发展；本句是“她看着，我突然进来”，不是同步变化。干扰点：as 也能译“当……时”，但语感是伴随。</li><li>D ❌ since 表“自从”，主句必须用完成时（has been watching），且句意会变成“自从我进来她就一直在看电视”，与“我进来时她在看”不同。干扰点：时态搭配没对上。</li></ul><p><strong>整句翻译</strong>：我进来的时候，她正在看电视。</p><p><strong>词组</strong>：<code>watch TV</code> 看电视；<code>come in</code> 进来</p><p><strong>对比自测</strong>：做完后对照 quiz:2，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 when 用法①）：① 从句为短暂动作、主句为持续动作；② 主从句均为短暂动作</p></details><p><strong>I will call you as soon as I ____ there.</strong></p><ul><li>A. will get</li><li>B. get</li><li>C. got</li><li>D. have got</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（get）</strong> —— 时间状语从句遵循“主将从现”，用一般现在时 get。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 时间状语从句不出现 will：主句已经是 will call，从句不能再写 will get，这正是“主将从现”的反面。</li><li>B ✅ 主句 I will call you 是将来时，时间状语从句 as soon as 遵循主将从现，用一般现在时 get。</li><li>C ❌ got 是一般过去时，与主句的将来时间错位；要表将来只能用一般现在时。干扰点：把从句当独立句子按时态一致处理。</li><li>D ❌ have got 是现在完成时，强调“已经到了”，而 as soon as 要的是“一到就”的那一刻；时态选错会让句子多出“已经完成”的意思。</li></ul><p><strong>整句翻译</strong>：我一到那儿就给你打电话。</p><p><strong>词组</strong>：<code>as soon as</code> 一……就……；<code>call sb.</code> 给某人打电话</p><p><strong>对比自测</strong>：做完后对照 quiz:28，比较两题的判断依据</p><p><strong>原文定位</strong>（课件“主将从现”）：I will call you when I arrive at the station.（我到车站时会给你打电话。）</p></details><p><strong>I was about to leave the office ____ the telephone rang.</strong></p><ul><li>A. when</li><li>B. while</li><li>C. as</li><li>D. until</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（when）</strong> —— 固定结构 be about to do...when...，“正要做某事，这时突然……”。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ be about to do...when... 是固定结构，表示“正要做某事，这时突然……”，when 引导的从句交代打断性的突发动作。</li><li>B ❌ while 表“在……期间”，不能进入 be about to do...when... 这个框架；而且 rang 是瞬间动作，与 while 要求的持续动作不符。</li><li>C ❌ as 表伴随或“随着”，语气上不能表达“正要……这时突然”，与句子的突发感不合。干扰点：as 与 when 都能译“当……时”，但两者的语义侧重不同。</li><li>D ❌ until 需要主句是延续动作或否定结构（didn&#39;t leave until…），“正要离开”不是一直等到某个时刻的动作。干扰点：把 until 也当成“当……时”。</li></ul><p><strong>整句翻译</strong>：我正要离开办公室，这时电话响了。</p><p><strong>词组</strong>：<code>be about to do sth.</code> 正要做某事；<code>the telephone rang</code> 电话响了</p><p><strong>对比自测</strong>：做完后对照 quiz:21，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 when 用法③）：用于 be doing...when...、be about to do...when... 等结构</p></details><p><strong>He didn’t go to bed ____ he finished his homework.</strong></p><ul><li>A. when</li><li>B. while</li><li>C. until</li><li>D. as</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（until）</strong> —— not...until... 表示“直到……才……”。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ when 只交代“在……的时候”，句子会读成“当他做完作业时，他没有睡觉”，与“直到……才”的语义不符。干扰点：把 not...until 的语感交给 when。</li><li>B ❌ while 要求从句动作持续，finish his homework 是一下子完成的动作；while 也不能与 not 构成“直到……才”。</li><li>C ✅ 主句 didn&#39;t go to bed 是否定式、go to bed 是非延续性动词，正是 not...until... 结构，译“直到……才”。</li><li>D ❌ as 表伴随或“随着”，同样无法表达“直到……才”的先后逻辑。</li></ul><p><strong>整句翻译</strong>：他直到做完作业才上床睡觉。</p><p><strong>词组</strong>：<code>go to bed</code> 上床睡觉（瞬间动作，非延续）；<code>finish one&#39;s homework</code> 完成作业</p><p><strong>对比自测</strong>：做完后对照 quiz:25，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 until/till 表）：否定句 not...until... 主句谓语为非延续性动词，动作到某时才开始，译为“直到……才”</p></details><p><strong>The children ran away ____ they saw the teacher.</strong></p><ul><li>A. as soon as</li><li>B. while</li><li>C. until</li><li>D. before</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（as soon as）</strong> —— 表示“一看见老师就跑开”，用 as soon as。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ “一……就……”的时间关系用 as soon as：看见老师的那一刻，跑开紧跟着发生。</li><li>B ❌ while 要求从句动作持续，saw 是瞬间动作；语意上也不是“在看见的这段时间里刚跑开”。</li><li>C ❌ until 需要主句是延续动作或否定式。ran away 是瞬间动作，“直到看见老师才跑开”也不符合句意。干扰点：只看到时间关系就乱套连词。</li><li>D ❌ before 表“在……之前”，会变成“在看见老师之前就跑开了”，与“一看见就跑”方向相反。干扰点：时间先后颠倒。</li></ul><p><strong>整句翻译</strong>：孩子们一看见老师就跑开了。</p><p><strong>词组</strong>：<code>run away</code> 跑开；<code>as soon as</code> 一……就……</p><p><strong>对比自测</strong>：做完后对照 quiz:32，比较两题的判断依据</p><p><strong>原文定位</strong>（课件“一……就……”）：as soon as：She called me as soon as she arrived at the airport.</p></details><p><strong>You should make it a rule to leave things ____ you can find them again easily.</strong></p><ul><li>A. when</li><li>B. where</li><li>C. then</li><li>D. there</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（where）</strong> —— where 引导地点状语从句：把物品放在以后容易找到的地方。（笔记标注为参考答案，课件未标）</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ when 引导时间从句，句子缺的是“地点”，不是时间。干扰点：只看到空格后是完整句子就随手填时间连词。</li><li>B ✅ 从句说明 leave 这个动作发生在“什么地方”，where 前没有地点先行词、直接修饰主句谓语，是地点状语从句。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ then 是副词“那时”，不是连词，不能连接 you can find them again easily 这个句子。干扰点：then 看起来像关系副词，其实只能作状语。</li><li>D ❌ there 同样是副词“那里”，不能引导从句；要表达“那个地方”必须用 where。干扰点：把 there 与 where 的“地点”含义混为一谈。</li></ul><p><strong>整句翻译</strong>：你应当养成习惯，把东西放在以后容易找到的地方。</p><p><strong>词组</strong>：<code>make it a rule to do sth.</code> 把……当作规矩、养成……的习惯；<code>leave sth. somewhere</code> 把某物留在某处</p><p><strong>对比自测</strong>：做完后对照 quiz:6，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 where 辨析）：地点状语从句：where 前没有表示地点的先行词，直接修饰主句谓语，where 是从属连词</p></details><p><strong>Medicine should not be kept ____ the children can easily reach.</strong></p><ul><li>A. when</li><li>B. where</li><li>C. which</li><li>D. that</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（where）</strong> —— 空处引导地点状语从句且在从句中作地点状语，应选 where；when 引导时间状语从句，which 与 that 常引导名词性从句或定语从句。句意：药品不应该放在孩子们能毫不费力够到的地方。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 句意讲的是存放的“地点”，when 引导时间从句，语义对不上。</li><li>B ✅ 空格处引导从句、说明药品存放的地点，空前的 kept 后面没有地点先行词，用 where 引导地点状语从句。</li><li>C ❌ which 是关系代词，要在从句里作主语或宾语，并且需要先行词；本句空格前没有可指代的名词。干扰点：见到从句就想填 which。</li><li>D ❌ that 引导定语从句或名词性从句时也要有先行词或在从句中充当成分，它不能在从句里作地点状语。干扰点：把 that 当成万能的从句引导词。</li></ul><p><strong>整句翻译</strong>：药品不应该放在孩子们能轻易够到的地方。</p><p><strong>词组</strong>：<code>keep sth. somewhere</code> 把某物存放于某处；<code>reach</code> 够到、伸手拿到</p><p><strong>对比自测</strong>：做完后对照 quiz:5，比较两题的判断依据</p><p><strong>原文定位</strong>（课件地点从句）：通常由 where、wherever 引导</p></details><p><strong>I didn’t go to the party last night ____ I was very tired.</strong></p><ul><li>A. because</li><li>B. if</li><li>C. though</li><li>D. until</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（because）</strong> —— “很累”是昨晚没去聚会的直接原因，用 because。（笔记标注为参考答案，课件未标）</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ “很累”是昨晚没去聚会的直接原因，用 because 引导原因状语从句。来源：课件未附答案，本条为笔记补充解析（阅读版亦注明“笔记标注为参考答案，课件未标”）。</li><li>B ❌ if 表条件，会读成“如果我当时很累，我就没去”，把已发生的事实写成假设，逻辑不通。</li><li>C ❌ though 表让步，前后应“与预期相反”；句子里“累”正是没去的原因，不是相反的情况。干扰点：把因果当成让步。</li><li>D ❌ until 要与否定延续结构搭配（didn&#39;t…until…），“直到我很累才没去聚会”讲不通。干扰点：只因为前面有否定词就选 until。</li></ul><p><strong>整句翻译</strong>：我昨晚没去参加聚会，因为我很累。</p><p><strong>词组</strong>：<code>go to the party</code> 去参加聚会；<code>last night</code> 昨晚（定下一般过去时）</p><p><strong>对比自测</strong>：做完后对照 quiz:9，比较两题的判断依据</p><p><strong>原文定位</strong>（课件原因连词表）：常见引导词：because、since（因为；既然）、as、for、now that（既然）</p></details><p><strong>____ we have finished the project, why don’t you take a week off?</strong></p><ul><li>A. But for</li><li>B. Ever since</li><li>C. Now that</li><li>D. Even if</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（Now that）</strong> —— Now that 表示“既然”，引导原因状语从句；But for 表“要不是”需接名词且常用于虚拟语气；Ever since 引导时间状语从句；Even if 引导让步状语从句。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ But for 表“要不是”，后面要接名词性成分且常与虚拟语气连用（But for your help, I would have failed.），不能接完整句子。干扰点：把它当成普通连词。</li><li>B ❌ Ever since 表“自从”，主句该用完成时；句意会变成“自从我们完成项目，你为什么不请假”，逻辑不通。</li><li>C ✅ Now that 表“既然”，把“项目已完成”当作已知前提引出建议，是原因状语从句中的“既然”一类。</li><li>D ❌ Even if 表“即使”，让步关系会读成“即使完成了项目，你为什么不休息”，与句意相反。干扰点：ever since / even if / now that 形近易混。</li></ul><p><strong>整句翻译</strong>：既然我们已经完成了这个项目，你为什么不休一周假呢？</p><p><strong>词组</strong>：<code>now that</code> 既然（引导原因从句）；<code>take a week off</code> 休一周假</p><p><strong>对比自测</strong>：做完后对照 quiz:22，比较两题的判断依据</p><p><strong>原文定位</strong>（课件原因从句）：now that（既然）</p></details><p><strong>The children were very excited these days ____ the Christmas party was to be held.</strong></p><ul><li>A. so</li><li>B. unless</li><li>C. if</li><li>D. because</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（because）</strong> —— 圣诞聚会即将举行是孩子们兴奋的原因，用 because。（笔记补充解析）</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ so 是并列连词“所以”，后面应接结果；本句空格前已经是结果（excited），空后给的是原因，方向反了。干扰点：把原因从句写成了结果从句。</li><li>B ❌ unless 表“除非”，会读成“除非要举行聚会，孩子们才兴奋”，条件关系与因果事实不符。</li><li>C ❌ if 表条件，把“要举行聚会”写成假设，与句中 these days 描述的事实不符。</li><li>D ✅ 空后 the Christmas party was to be held 是孩子们兴奋的原因，用 because。（课件未附答案，本条为笔记补充解析）</li></ul><p><strong>整句翻译</strong>：这些天孩子们非常兴奋，因为要举行圣诞聚会了。</p><p><strong>词组</strong>：<code>the Christmas party</code> 圣诞聚会；<code>be to be held</code> 将要举行（be to do 表将来）</p><p><strong>对比自测</strong>：做完后对照 quiz:7，比较两题的判断依据</p><p><strong>原文定位</strong>（课件原因从句连词）：because、since（因为；既然）、as、for、now that（既然）</p></details><p><strong>You need to practise talking to each other ____ you want to speak fluent English.</strong></p><ul><li>A. or</li><li>B. if</li><li>C. though</li><li>D. where</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（if）</strong> —— 想说流利英语是需要互相练习交谈的条件，用 if。（笔记标注为参考答案，课件未标）</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ or 是并列连词，表“或者、否则”，不能引导条件从句（只在“祈使句 + or + 句子”里表否则）。</li><li>B ✅ “想说流利英语”是“需要练习”的前提条件，用 if 引导条件状语从句。来源：笔记标注为参考答案，课件未标。</li><li>C ❌ though 表让步，前后应相反；这里“想学好”正是“要练习”的理由，方向一致。干扰点：把条件句当让步句。</li><li>D ❌ where 引导地点从句，句中没有任何地点含义。干扰点：看到空格在句首就乱选引导词。</li></ul><p><strong>整句翻译</strong>：如果你想说出流利的英语，就需要互相练习对话。</p><p><strong>词组</strong>：<code>practise doing sth.</code> 练习做某事（practise 后接动名词）；<code>fluent English</code> 流利的英语</p><p><strong>对比自测</strong>：做完后对照 quiz:12，比较两题的判断依据</p><p><strong>原文定位</strong>（课件条件从句）：在时间状语从句和条件状语从句中，若主句用一般将来时，从句用一般现在时表示将来</p></details><p><strong>Remember my phone number ____ you need my help one day.</strong></p><ul><li>A. ever since</li><li>B. even if</li><li>C. as soon as</li><li>D. in case</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（in case）</strong> —— 记住电话号码是“以防”将来需要帮助，in case 符合语义。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ ever since 表“自从”，主句要用完成时，且句意会变成“自从你需要帮忙就记号码”，先后颠倒。干扰点：与 in case 形近的是 even if，与 ever since 只差一词。</li><li>B ❌ even if 表“即使”，让步关系；记住号码不是“即使你需要帮忙也不记”的意思。</li><li>C ❌ as soon as 表“一……就……”，会读成“你一需要帮忙就记号码”——那时候才记已经来不及，逻辑颠倒。</li><li>D ✅ in case 表“万一、以防”，说明“记号码”是为防备将来可能出现的需要，符合句意。</li></ul><p><strong>整句翻译</strong>：记下我的电话号码，以防哪天你需要我帮忙。</p><p><strong>词组</strong>：<code>in case</code> 万一、以防（引导目的/条件从句）；<code>one day</code> 某一天（将来）</p><p><strong>对比自测</strong>：做完后对照 quiz:12，比较两题的判断依据</p><p><strong>原文定位</strong>（课件条件从句连词）：in case（万一）</p></details><p><strong>You can join us in this activity ____ you follow these rules strictly.</strong></p><ul><li>A. on condition that</li><li>B. just as</li><li>C. now that</li><li>D. lest</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（on condition that）</strong> —— 严格遵守规则是参加活动的条件，on condition that 表示“条件是”。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ on condition that 表“条件是、只要”，把“遵守规则”设为参加活动的前提，是条件状语从句。</li><li>B ❌ just as 表“正如”，引导方式从句（Just as we sweep our rooms, so…），不表条件。干扰点：as 系列连词多，容易与条件义混。</li><li>C ❌ now that 表“既然”，把“遵守规则”当成既成事实的因果，而句中说的是加入活动前必须满足的条件。</li><li>D ❌ lest 表“以免”，常接虚拟（lest he should fail），语气是防备坏结果，与“只要……就可以”完全不同。</li></ul><p><strong>整句翻译</strong>：只要你严格遵守这些规则，就可以参加我们的这个活动。</p><p><strong>词组</strong>：<code>join sb. in an activity</code> 和某人一起参加活动；<code>follow the rules strictly</code> 严格遵守规则</p><p><strong>对比自测</strong>：做完后对照 quiz:11，比较两题的判断依据</p><p><strong>原文定位</strong>（课件条件从句连词表）：on condition that（条件是）</p></details><p><strong>We have to get that car fixed ____.</strong></p><ul><li>A. no matter it costs how much</li><li>B. no matter how much costs it</li><li>C. no matter how much it costs</li><li>D. no matter how much does it cost</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（no matter how much it costs）</strong> —— no matter how much 后接陈述语序 it costs。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 语序错乱：no matter 后面必须紧跟疑问词 how，不能先出现主语 it。干扰点：把 no matter 当成独立成分。</li><li>B ❌ 主语 it 跑到了谓语 costs 后面，从句倒装了；no matter how 引导的从句用陈述语序。干扰点：把 however 从句当成疑问句。</li><li>C ✅ no matter how much 后接陈述语序 it costs：no matter + 疑问词引导让步从句，且从句不倒装。</li><li>D ❌ 多加了助动词 does 并把它前置：让步从句既不需要 do 支持，也不倒装。</li></ul><p><strong>整句翻译</strong>：不管花多少钱，我们都得把那辆车修好。</p><p><strong>词组</strong>：<code>get sth. fixed</code> 把某物修好（get + 宾语 + 过去分词）；<code>no matter how much</code> 无论多少（后接形容词/副词 + 陈述语序从句）</p><p><strong>对比自测</strong>：做完后对照 quiz:14，比较两题的判断依据</p><p><strong>原文定位</strong>（课件让步结构③）：no matter + 疑问词 = 疑问词 + -ever</p></details><p><strong>If you work with a strong will, you can overcome the difficulty, ____ great it is.</strong></p><ul><li>A. what</li><li>B. however</li><li>C. whatever</li><li>D. how</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（however）</strong> —— however + 形容词 + 主语 + 谓语，表示“无论多么……”。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ what 既不能修饰形容词 great，也不表让步。干扰点：以为疑问词随便哪个都能表“无论……”。</li><li>B ✅ however = no matter how，后面接形容词 great，表示“无论困难多大”，引导让步状语从句。</li><li>C ❌ whatever 后面要接名词（whatever difficulty）；great 是形容词，不能跟在 whatever 后面。干扰点：whatever 与 however 只差几个字母，一个接名词、一个接形容词或副词。</li><li>D ❌ how 不引导让步状语从句，它要么引感叹句，要么引名词性从句。干扰点：看到形容词就填 how。</li></ul><p><strong>整句翻译</strong>：如果你带着坚强的意志去做，无论困难多大，你都能克服。</p><p><strong>词组</strong>：<code>work with a strong will</code> 带着坚强的意志去做；<code>overcome the difficulty</code> 克服困难</p><p><strong>对比自测</strong>：做完后对照 quiz:15，比较两题的判断依据</p><p><strong>原文定位</strong>（课件让步结构③）：no matter how = however</p></details><p><strong>____ difficulty they may come across, they’ll help one another to overcome it.</strong></p><ul><li>A. Whatever</li><li>B. Whenever</li><li>C. However</li><li>D. Wherever</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（Whatever）</strong> —— difficulty 是名词，用 whatever + 名词。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ difficulty 是名词，whatever + 名词表“无论什么困难”，与 no matter what 等价。</li><li>B ❌ Whenever 表“无论何时”，句中没有任何时间含义。干扰点：四个选项都以 -ever 结尾，只凭词形选。</li><li>C ❌ However 后面要接形容词或副词（however great the difficulty is），不能直接接名词 difficulty。</li><li>D ❌ Wherever 表“无论何地”，句子讲的是困难不是地点。</li></ul><p><strong>整句翻译</strong>：无论他们遇到什么困难，都会互相帮助去克服它。</p><p><strong>词组</strong>：<code>come across</code> 遇到、碰上；<code>help one another</code> 互相帮助</p><p><strong>对比自测</strong>：做完后对照 quiz:14，比较两题的判断依据</p><p><strong>原文定位</strong>（课件让步结构③）：疑问词 + -ever 既能引导名词性从句，也能引导让步状语从句</p></details><p><strong>____ Cindy joined the company only one year ago, she has been promoted twice.</strong></p><ul><li>A. Because</li><li>B. If</li><li>C. Although</li><li>D. When</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（Although）</strong> —— 前后是让步关系：虽然入职仅一年，却已晋升两次。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ Because 把后半句当成原因——“因为才入职一年，所以升职两次”，与新员工升职慢的常理相反。干扰点：只看中文顺不顺，不看逻辑方向。</li><li>B ❌ If 表条件，而句中是已发生的事实（joined one year ago、has been promoted），不是假设。</li><li>C ✅ 前后“入职仅一年”与“已升两次”形成与预期相反的对比，用 Although 引导让步从句。</li><li>D ❌ When 表时间，会读成“她一年前入职时已经升职两次”，时间关系颠倒。</li></ul><p><strong>整句翻译</strong>：尽管辛迪一年前才进公司，却已经升了两次职。</p><p><strong>词组</strong>：<code>join the company</code> 入职、加入公司；<code>be promoted</code> 被提拔、升职</p><p><strong>对比自测</strong>：做完后对照 quiz:26，比较两题的判断依据</p><p><strong>原文定位</strong>（课件让步从句）：二者引导让步状语从句时，不能与 but 连用；但 though 可与 yet 连用</p></details><p><strong>He made ____ great progress ____ his parents were very pleased with him.</strong></p><ul><li>A. so; that</li><li>B. such; that</li><li>C. so a; that</li><li>D. such a; that</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（such; that）</strong> —— progress 是不可数名词，结构为 such + 形容词 + 名词 + that。（课件未附答案，笔记补充解析）</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ so 后面要接形容词或副词，不能直接接“形容词 + 名词”。干扰点：so great 单看很顺，一接 progress 就错。</li><li>B ✅ progress 是不可数名词，结构是 such + 形容词 + 不可数名词 + that。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ so a 语序不合法：so 不能直接带冠词再接名词，只有 so + adj. + a + 名词（so clever a boy）这种顺序。</li><li>D ❌ such a 只能接可数名词单数，progress 不可数，不能加 a。干扰点：习惯性写成 such a。</li></ul><p><strong>整句翻译</strong>：他进步这么大，他父母对他非常满意。</p><p><strong>词组</strong>：<code>make progress</code> 取得进步（progress 不可数）；<code>be pleased with sb.</code> 对某人满意</p><p><strong>对比自测</strong>：做完后对照 quiz:18，比较两题的判断依据</p><p><strong>原文定位</strong>（课件口诀）：名前 such，形副 so；that 从句跟在后。多多少少必用 so</p></details><p><strong>The film was ____ boring ____ I fell asleep in the cinema.</strong></p><ul><li>A. such; that</li><li>B. so; that</li><li>C. very; that</li><li>D. too; to</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（so; that）</strong> —— boring 是形容词，结构为 so + 形容词 + that。（课件未附答案，笔记补充解析）</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ such 后面必须接名词（such a boring film），不能直接接形容词 boring。干扰点：只记“如此”，不分词性。</li><li>B ✅ boring 是形容词，结构为 so + 形容词 + that。来源：课件未附答案，本条为笔记补充解析。</li><li>C ❌ very 是副词，不能与 that 从句构成“如此……以致……”结构，very...that 不是搭配。干扰点：very 与 so 都表程度，但 very 不能带结果从句。</li><li>D ❌ too...to 表“太……而不能”，to 后要接动词原形；本句后面是完整句子，且语义相反（睡着是因为太无聊，不是“不能睡”）。</li></ul><p><strong>整句翻译</strong>：这部电影太没意思了，我在电影院里睡着了。</p><p><strong>词组</strong>：<code>fall asleep</code> 入睡、睡着了；<code>in the cinema</code> 在电影院</p><p><strong>对比自测</strong>：做完后对照 quiz:17，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 so...that 例句）：The movie is so interesting that I want to watch it again.</p></details><p><strong>It is known to all that ____ you exercise regularly, you won’t keep good health.</strong></p><ul><li>A. unless</li><li>B. whenever</li><li>C. although</li><li>D. if</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（unless）</strong> —— unless = if...not：除非经常锻炼，否则不能保持健康。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ unless = if...not，主句是否定的结果（won&#39;t keep good health），条件是“不锻炼”，正好对应“除非……否则”。</li><li>B ❌ whenever 表“无论何时”，把条件换成了时间，句意变成“无论什么时候锻炼都不能保持健康”。</li><li>C ❌ although 让步会读成“尽管经常锻炼，也保持不了健康”，与常识相反。</li><li>D ❌ if 是“如果经常锻炼，就保持不了健康”，语义正好相反。干扰点：if 与 unless 只差一个否定，要先看清主句的肯否。</li></ul><p><strong>整句翻译</strong>：众所周知，除非你经常锻炼，否则就不能保持健康。</p><p><strong>词组</strong>：<code>It is known to all that…</code> 众所周知……；<code>keep good health</code> 保持健康</p><p><strong>对比自测</strong>：做完后对照 quiz:27，比较两题的判断依据</p><p><strong>原文定位</strong>（课件条件从句）：Let’s go out for a walk unless you are too tired.（除非你太累了，否则我们出去散步吧。）</p></details><p><strong>____ I can see, there is only one possible way to keep away from the danger.</strong></p><ul><li>A. As long as</li><li>B. As far as</li><li>C. Even though</li><li>D. Even if</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（As far as）</strong> —— 固定表达 as far as I can see，意为“据我所见”。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ as long as 表“只要”，引导条件从句；本句不是条件，而是“就……而言”的范围限定。干扰点：as far as 与 as long as 只差一个单词。</li><li>B ✅ as far as I can see 是固定表达，“据我所见”，用来限定判断的范围。</li><li>C ❌ Even though 表“尽管”，让步关系与该句“据我所见”的限定不符。</li><li>D ❌ Even if 表“即使”，同样不表“据……判断”。干扰点：Even though 与 Even if 都表让步，与这句毫无关系。</li></ul><p><strong>整句翻译</strong>：就我所见，只有一种可能的方法能避开这种危险。</p><p><strong>词组</strong>：<code>as far as I can see</code> 据我所见（固定表达，表判断范围）；<code>keep away from</code> 远离、避开</p><p><strong>对比自测</strong>：做完后对照 quiz:31，比较两题的判断依据</p><p><strong>原文定位</strong>（课件短语辨析）：as/so long as（只要）</p></details><p><strong>We were about to leave ____ it began to rain.</strong></p><ul><li>A. when</li><li>B. while</li><li>C. as</li><li>D. during</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（when）</strong> —— be about to do...when...，正要做某事时突然……。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ be about to do...when... 是固定结构，“正要做某事，这时突然……”。</li><li>B ❌ while 只表“在……期间”，要求从句动作持续，began 是瞬间动作。</li><li>C ❌ as 强调伴随、随着，不能表达“正要……这时突然”的打断感。</li><li>D ❌ during 是介词，只能接名词短语（during the rain），不能接句子 it began to rain。干扰点：during 与 when 都表时间，但词性根本不同。</li></ul><p><strong>整句翻译</strong>：我们正要离开，这时下起雨来了。</p><p><strong>词组</strong>：<code>be about to do sth.</code> 正要做某事；<code>begin to do sth.</code> 开始做某事</p><p><strong>对比自测</strong>：做完后对照 quiz:2，比较两题的判断依据</p><p><strong>原文定位</strong>（课件易错）：when 可接短暂动作，也可用于“正在/正要……这时……”；while 更常接持续动作或进行时</p></details><p><strong>The day must be breaking, ____ the birds have begun singing.</strong></p><ul><li>A. because</li><li>B. as</li><li>C. for</li><li>D. since</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（for）</strong> —— for 补充说明推断理由：鸟已开始鸣叫，所以天一定快亮了。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ because 表直接原因，而“鸟叫”不是天亮的原因，只是推断的根据；主句的 must be 已经说明这是在推测。干扰点：because 与 for 都译“因为”，一个讲原因、一个讲推断理由。</li><li>B ❌ as 表“因为”时讲的也是原因，且通常表示已知、明显的理由，用在这里会丢掉“由现象推断”的语感。</li><li>C ✅ for 是并列连词，用后一分句补充说明推断的理由：由鸟叫推断天快亮，语气比 because 弱，常放主句之后。</li><li>D ❌ since 表“既然”，用于已知前提，一般不放在主句之后充当推断依据。</li></ul><p><strong>整句翻译</strong>：天一定快亮了，因为鸟儿已经开始鸣叫了。</p><p><strong>词组</strong>：<code>the day must be breaking</code> 天一定快亮了（must be 表肯定推测）；<code>begin doing sth.</code> 开始做某事</p><p><strong>对比自测</strong>：做完后对照 quiz:8，比较两题的判断依据</p><p><strong>原文定位</strong>（课件原因连词表）：because、since（因为；既然）、as、for、now that（既然）</p></details><p><strong>You are free to go ____ you like.</strong></p><ul><li>A. there</li><li>B. where</li><li>C. wherever</li><li>D. when</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（wherever）</strong> —— wherever 表示“无论你喜欢去哪里”。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ there 是副词，不能引导从句。干扰点：there 也能表地点，但它是状语不是连词。</li><li>B ❌ where 只表示确定的地点“在……的地方”，表达不出“愿意去哪儿就去哪儿”的任意性。干扰点：where 与 wherever 只差一个后缀。</li><li>C ✅ wherever = no matter where，表“无论哪里”，引导地点状语从句，正好对应“爱去哪儿去哪儿”。</li><li>D ❌ when 表时间，句子讲的是地点。</li></ul><p><strong>整句翻译</strong>：你愿意去哪儿就去哪儿。</p><p><strong>词组</strong>：<code>be free to do sth.</code> 可以自由做某事；<code>wherever</code> 无论哪里（= no matter where）</p><p><strong>对比自测</strong>：做完后对照 quiz:5，比较两题的判断依据</p><p><strong>原文定位</strong>（课件地点从句）：通常由 where、wherever 引导</p></details><p><strong>I hurried ____ I wouldn’t be late for class.</strong></p><ul><li>A. since</li><li>B. so that</li><li>C. as if</li><li>D. unless</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（so that）</strong> —— 匆忙的目的是不迟到，so that 引导目的状语从句。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ since 表“因为、既然”，会把“不迟到”说成赶路的原因，方向反了。干扰点：中文“为的是”与“因为”都要译成连词，容易混淆。</li><li>B ✅ so that 引导目的状语从句，从句用 wouldn&#39;t（情态动词过去式）说明“为的是不迟到”。</li><li>C ❌ as if 表“仿佛”，引导方式从句，与目的无关。</li><li>D ❌ unless 表“除非”，是条件关系，句子缺的是目的。</li></ul><p><strong>整句翻译</strong>：我匆匆忙忙地赶路，为的是上课不迟到。</p><p><strong>词组</strong>：<code>be late for class</code> 上课迟到；<code>so that</code> 以便（引导目的状语从句）</p><p><strong>对比自测</strong>：做完后对照 quiz:37，比较两题的判断依据</p><p><strong>原文定位</strong>（课件目的从句）：常由 so that（以便）、in order that、in case（以备；以防）引导，从句中通常使用情态动词</p></details><p><strong>I ____ until he came.</strong></p><ul><li>A. left</li><li>B. didn’t leave</li><li>C. hadn’t left</li><li>D. would leave</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（didn’t leave）</strong> —— not...until... 表示“直到他来我才离开”。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 肯定式 left...until 表“一直离开到他来”，leave 是瞬间动词，动作无法延续到某个时刻。干扰点：把 not...until 里的否定丢了。</li><li>B ✅ leave 是非延续性动词，要用否定式 not...until 才能表示“到那时才离开”。</li><li>C ❌ hadn&#39;t left 是过去完成时的否定，会读成“他来的时候我还没离开”，时态与语义都不是“直到他来才离开”。</li><li>D ❌ would leave 表过去将来，无法表达“直到……才”的实现时点。干扰点：只看到过去的语境就选带过去意义的时态。</li></ul><p><strong>整句翻译</strong>：直到他来，我才离开。</p><p><strong>词组</strong>：<code>not...until...</code> 直到……才……；<code>leave</code> 离开（非延续性动词）</p><p><strong>对比自测</strong>：做完后对照 quiz:3，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 until 对照表）：I didn&#39;t leave until he arrived.（直到他来，我才离开。）</p></details><p><strong>I still like the building in my village, ____ it is rather old and nearly falls down.</strong></p><ul><li>A. though</li><li>B. as</li><li>C. if</li><li>D. where</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（though）</strong> —— 建筑虽旧且将倒塌，我仍喜欢它，though 引导让步从句。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ though 引导让步从句，前后形成“旧得几乎要塌 ↔ 我仍然喜欢”的对比。</li><li>B ❌ as 表“虽然”时必须倒装（Old as it is…），本句是正常语序，所以 as 在这里只能读成“因为/当……时”。干扰点：as 确实能表让步，但必须倒装。</li><li>C ❌ if 表条件，句中是已存在的事实，不是假设。</li><li>D ❌ where 表地点，从句里没有地点含义。</li></ul><p><strong>整句翻译</strong>：我仍然喜欢村里的那座建筑，虽然它相当旧，几乎要塌了。</p><p><strong>词组</strong>：<code>fall down</code> 倒塌；<code>rather</code> 相当、颇</p><p><strong>对比自测</strong>：做完后对照 quiz:33，比较两题的判断依据</p><p><strong>原文定位</strong>（课件让步 as 倒装）：as 表示“虽然、尽管”时，必须把表语、状语或动词原形提前</p></details><p><strong>____ the government agree to give extra money, the theater will have to close next week.</strong></p><ul><li>A. Unless</li><li>B. If</li><li>C. Since</li><li>D. As</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（Unless）</strong> —— 除非政府同意追加资金，否则剧院将关闭。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ “政府追加资金”是剧院不关门的唯一条件，主句是消极结果，用 unless（除非……否则）。（从句用动词原形 agree，属正式文体的用法。）</li><li>B ❌ If 表“如果”，会读成“如果政府同意给钱，剧院就得关门”，与常理相反。干扰点：if 与 unless 的肯否要按主句结果来定。</li><li>C ❌ Since 表“既然”，把还没发生的事当成既成前提，逻辑不成立。</li><li>D ❌ As 表“因为/随着”，语义不通。干扰点：As 与 Unless 都以元音开头，读题太快容易看错词。</li></ul><p><strong>整句翻译</strong>：除非政府同意追加资金，否则剧院下周将不得不关门。</p><p><strong>词组</strong>：<code>agree to do sth.</code> 同意做某事；<code>extra money</code> 额外的资金</p><p><strong>对比自测</strong>：做完后对照 quiz:19，比较两题的判断依据</p><p><strong>原文定位</strong>（课件条件从句连词）：unless（除非）</p></details><p><strong>It will be a while ____ we know the results of the experiments.</strong></p><ul><li>A. once</li><li>B. before</li><li>C. after</li><li>D. when</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（before）</strong> —— It will be + 一段时间 + before...：要过一段时间才……。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ once 表“一旦”，强调条件成熟那一刻，表达不出“要过一段时间才”。</li><li>B ✅ It will be + 一段时间 + before... 是固定句型，表示“要过多久才……”，从句用一般现在时。</li><li>C ❌ after 表“在……之后”，句子会变成“我们知道结果之后再过一段时间”，先后颠倒。</li><li>D ❌ when 表“当……时候”，不能表达“过一段时间才”的时间跨度。干扰点：when 也能引导时间从句，但 It will be + 时间段 之后固定用 before。</li></ul><p><strong>整句翻译</strong>：要过一段时间我们才能知道实验的结果。</p><p><strong>词组</strong>：<code>It will be a while before…</code> 要过一段时间才……；<code>the results of the experiments</code> 实验的结果</p><p><strong>对比自测</strong>：做完后对照 quiz:36，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 It 句型（第 16 课 It 易混句型表））：It will (not) be + 时间段 + before + 一般现在时</p></details><p><strong>Many of them turned a deaf ear to his advice, ____ they knew it was valuable.</strong></p><ul><li>A. as if</li><li>B. now that</li><li>C. even though</li><li>D. so that</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（even though）</strong> —— 即使知道建议有价值，许多人仍置若罔闻，even though 表让步。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ as if 表“仿佛”，引导方式从句，从句内容应是“像什么样子”；而句中 they knew it was valuable 是已发生的事实，不是比喻。</li><li>B ❌ now that 表“既然”，会把“知道有价值”当成他们不听的原因，语义恰好相反。</li><li>C ✅ even though 表“尽管”，前后“知道有价值 ↔ 仍然不听”形成与预期相反的让步关系。</li><li>D ❌ so that 表目的，“为了让他们知道有价值”讲不通。干扰点：把让步句写成目的句。</li></ul><p><strong>整句翻译</strong>：他们中许多人对他提的建议置若罔闻，尽管知道这建议很有价值。</p><p><strong>词组</strong>：<code>turn a deaf ear to sth.</code> 对……置若罔闻；<code>be of value</code> 有价值</p><p><strong>对比自测</strong>：做完后对照 quiz:16，比较两题的判断依据</p><p><strong>原文定位</strong>（课件让步结构）：even if / even though（即使；尽管）</p></details><p><strong>____ decision my good friend Tom makes, I will support it heart and soul.</strong></p><ul><li>A. No matter how</li><li>B. No matter what</li><li>C. Whoever</li><li>D. However</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（No matter what）</strong> —— decision 是名词，用 no matter what + 名词。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ no matter how 后面要接形容词或副词（no matter how hard she tried），不能直接接名词 decision。</li><li>B ✅ 空格后紧跟名词 decision，no matter what + 名词表“无论什么决定”，从句用陈述语序 Tom makes。</li><li>C ❌ Whoever 指“无论谁”，在从句中作主语指人；本句从句的主语已是 Tom，缺的是修饰 decision 的“什么”。</li><li>D ❌ However = no matter how，只能修饰形容词或副词。干扰点：把“无论什么”笼统记成 however。</li></ul><p><strong>整句翻译</strong>：我的好朋友汤姆无论做什么决定，我都会全心全意支持。</p><p><strong>词组</strong>：<code>make a decision</code> 做决定；<code>heart and soul</code> 全心全意地</p><p><strong>对比自测</strong>：做完后对照 quiz:15，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 no matter 系列）：no matter what = whatever；no matter how = however</p></details><p><strong>They will finish the task before the deadline ____ they are given enough support.</strong></p><ul><li>A. in that</li><li>B. as far as</li><li>C. as long as</li><li>D. in case</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（as long as）</strong> —— 只要获得足够支持就能按时完成，as long as 表条件。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ in that 表“因为、由于”，引导原因，与“给支持 → 完成”的条件关系不符。干扰点：in that 与 in case 都以 in 开头。</li><li>B ❌ as far as 表“就……而言”（as far as I can see），不表条件。干扰点：as far as 与 as long as 只差一个单词。</li><li>C ✅ as long as 表“只要”，把“足够的支持”设为完成任务的条件。</li><li>D ❌ in case 表“万一、以防”，是防备性的，语义与“只要”不同。</li></ul><p><strong>整句翻译</strong>：只要给他们足够的支持，他们就会在截止日期前完成任务。</p><p><strong>词组</strong>：<code>before the deadline</code> 在截止日期之前；<code>as long as</code> 只要（引导条件从句）</p><p><strong>对比自测</strong>：做完后对照 quiz:20，比较两题的判断依据</p><p><strong>原文定位</strong>（课件条件从句）：You will succeed as long as you don&#39;t lose heart.</p></details><p><strong>I will pay a visit to my old friends ____ she comes back from abroad.</strong></p><ul><li>A. the time when</li><li>B. the moment when</li><li>C. on the minute</li><li>D. the minute</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：D（the minute）</strong> —— the minute 可直接作连词，表示“一……就……”。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ the time when 不是连词短语：the time 本身就能作连词，再加 when 就成了两个引导词挤在一起。干扰点：把 the moment when 这类名词短语的结构套进来。</li><li>B ❌ the moment when 同理：the moment 已经是从属连词，后面直接跟从句，不再加 when（the moment when 只在 the moment 作先行词时才成立）。</li><li>C ❌ on the minute 是介词短语，不能引导从句，且它的意思是“准时”。</li><li>D ✅ the minute 可以直接作连词，等于 as soon as，表示“一……就……”，后面直接跟 she comes back from abroad。</li></ul><p><strong>整句翻译</strong>：她一从国外回来，我就去拜访我的老朋友。</p><p><strong>词组</strong>：<code>pay a visit to sb.</code> 拜访某人；<code>the minute</code> 一……就……（可作连词的时间名词）</p><p><strong>对比自测</strong>：做完后对照 quiz:4，比较两题的判断依据</p><p><strong>原文定位</strong>（课件其他时间连词）：the moment / the minute / the instant（一……就……）</p></details><p><strong>____ it was, traffic in the downtown area was already building up.</strong></p><ul><li>A. While</li><li>B. Although</li><li>C. As</li><li>D. When</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（As）</strong> —— 课件原标记为 As；笔记指出 PDF 题干疑有缺字（未显示倒装应提前的表语），按课件标记保留答案，不擅自补写。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ 存疑：单看现有文字，While 作时间从句也讲得通（“当……的时候”），与标答 As 冲突。本条按课件标记的答案保留，并标出疑点。</li><li>B ❌ 存疑：Although 表让步、且不倒装，语义上也通，但与课件标记的 As 冲突。本条标记存疑：题干可能缺了倒装时应提前的表语。</li><li>C ✅ 存疑：课件标记答案为 As。按 as 引导让步从句必须倒装这条规则，题干应缺一个被提前的表语（如 Early as it was = 尽管时间还早），现有文字未显示该词，因此按课件答案保留 As，不擅自补写题干。</li><li>D ❌ 存疑：When 作时间从句也读得通，与标答冲突。本条按课件标记的答案不选它，并标记疑点。</li></ul><p><strong>整句翻译</strong>：（题干疑有缺字，按课件标记的答案 As 理解）尽管（时间）还早，市中心的交通已经在堵起来了。</p><p><strong>词组</strong>：<code>build up</code> 逐渐增多、聚集；<code>the downtown area</code> 市中心</p><p><strong>对比自测</strong>：做完后对照 quiz:26，比较两题的判断依据</p><p><strong>原文定位</strong>（阅读版解析（复核记录））：课件原标记为 As；笔记指出 PDF 题干疑有缺字（未显示倒装应提前的表语），按课件标记保留答案，不擅自补写</p></details><p><strong>You’d better visit Shangri-La（香格里拉）____ the weather is at its mildest in spring or autumn.</strong></p><ul><li>A. wherever</li><li>B. unless</li><li>C. when</li><li>D. though</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：C（when）</strong> —— when 引导时间状语从句：在春秋气候最温和时游览。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ wherever 表“无论哪里”，而从句说的是时间（in spring or autumn），地点连词接不上。干扰点：把 -ever 词一律当成“无论”。</li><li>B ❌ unless 表“除非”，条件关系讲不通——去香格里拉不是“除非天气好”。</li><li>C ✅ 从句说明“去”的时间：春秋天气最温和时，用 when 引导时间状语从句。</li><li>D ❌ though 表“虽然”，让步关系与句意不符。</li></ul><p><strong>整句翻译</strong>：你最好在春秋天气最宜人的时候去香格里拉。</p><p><strong>词组</strong>：<code>You&#39;d better do sth.</code> 你最好做某事；<code>at its mildest</code> 在最温和的时候</p><p><strong>对比自测</strong>：做完后对照 quiz:35，比较两题的判断依据</p><p><strong>原文定位</strong>（课件时间从句）：常见引导词：when、while、as、before、after、since、until、as soon as</p></details><p><strong>____ we were staying in China, we saw many interesting things.</strong></p><ul><li>A. Though</li><li>B. While</li><li>C. After</li><li>D. During</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（While）</strong> —— while 后接完整从句，表示在中国停留期间；during 是介词，不能接句子。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ Though 表让步，前后应相反；本句没有相反关系。</li><li>B ✅ 从句 we were staying in China 用过去进行时表持续，while 表“在……期间”，两段同时进行。</li><li>C ❌ After 表“在……之后”，会读成“离开中国之后才看到许多有趣的东西”，与句意相反。</li><li>D ❌ During 是介词，只能接名词短语（during our stay），不能接句子 we were staying…。干扰点：during 与 while 意思相近，但一个是介词、一个是连词。</li></ul><p><strong>整句翻译</strong>：我们在中国逗留期间，看到了许多有趣的东西。</p><p><strong>词组</strong>：<code>stay in China</code> 待在中国；<code>interesting things</code> 有趣的事物</p><p><strong>对比自测</strong>：做完后对照 quiz:34，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 when/while/as 表（while 行））：① 多与进行时搭配；② 可对比两种情况</p></details><p><strong>A prisoner escaped from prison last night. It wasn’t long ____ the guards discovered what had happened.</strong></p><ul><li>A. until</li><li>B. before</li><li>C. since</li><li>D. when</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（before）</strong> —— It wasn’t long before...：没过多久就……。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ until 需要主句是延续动作或否定延续结构；“时间不长”是时间跨度，不是延续动作，It wasn&#39;t long until 不成立。</li><li>B ✅ It wasn&#39;t long before... 是固定句型，“没过多久就……”，从句用一般过去时 discovered。</li><li>C ❌ since 表“自从”，主句该用完成时，语义也是“自从……过了多久”，与“没过多久就”相反。干扰点：since 前面也能跟时间，但结构要求不同。</li><li>D ❌ when 表“当……时候”，不能表达“没过多久就”的时间跨度。</li></ul><p><strong>整句翻译</strong>：昨晚一名囚犯越狱了。没过多久，警卫就发现了发生的事。</p><p><strong>词组</strong>：<code>escape from prison</code> 越狱；<code>It wasn&#39;t long before…</code> 没过多久就……</p><p><strong>对比自测</strong>：做完后对照 quiz:28，比较两题的判断依据</p><p><strong>原文定位</strong>（课件 It 句型（第 16 课 It 易混句型表））：It was (not) + 时间段 + before + 一般过去时：过了很久才/没过多久就</p></details><p><strong>I’d like to arrive 20 minutes earlier ____ I can have time for a cup of tea.</strong></p><ul><li>A. as soon as</li><li>B. so that</li><li>C. in case</li><li>D. as a result</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：B（so that）</strong> —— 提前到达的目的是留出喝茶时间，so that 引导目的从句。</p><p><strong>逐选项解析</strong></p><ul><li>A ❌ as soon as 表“一……就……”，是时间关系，句意不通。</li><li>B ✅ 早到 20 分钟的目的是留出喝茶时间，so that 引导目的从句，从句用情态动词 can。</li><li>C ❌ in case 表“以防万一”，防备的是可能出现的坏情况；喝茶不是需要防备的风险。</li><li>D ❌ as a result 是副词性短语“结果”，不能引导从句，而且它表结果、不表目的。</li></ul><p><strong>整句翻译</strong>：我想早到 20 分钟，这样我就有时间喝杯茶。</p><p><strong>词组</strong>：<code>have time for sth.</code> 有时间做某事；<code>so that</code> 以便（引导目的从句）</p><p><strong>对比自测</strong>：做完后对照 quiz:24，比较两题的判断依据</p><p><strong>原文定位</strong>（课件目的从句）：常由 so that（以便）、in order that、in case（以备；以防）引导，从句中通常使用情态动词</p></details><p><strong>Peter had to work hard day and night ____ he could earn more to pay for his new house.</strong></p><ul><li>A. in order that</li><li>B. in case that</li><li>C. provided that</li><li>D. on condition that</li></ul><details class="hint-container details"><summary>点开核对答案</summary><p><strong>答案：A（in order that）</strong> —— 日夜工作的目的是赚更多钱，in order that 引导目的从句。</p><p><strong>逐选项解析</strong></p><ul><li>A ✅ in order that 引导目的从句，比 so that 更正式，从句用情态动词 could。</li><li>B ❌ in case that 表“以防”，防备性目的；“多挣钱”不是要防备的事，而且 in case 通常不接 that。干扰点：in case 与 in order 都以 in 开头。</li><li>C ❌ provided that 表“倘若”，把“能多挣钱”变成条件，逻辑颠倒。</li><li>D ❌ on condition that 表“条件是”，同样是条件关系，不是目的。</li></ul><p><strong>整句翻译</strong>：彼得不得不日夜辛苦工作，以便能多挣点钱来付新房的钱。</p><p><strong>词组</strong>：<code>day and night</code> 日日夜夜；<code>pay for sth.</code> 为……付款</p><p><strong>对比自测</strong>：做完后对照 quiz:37，比较两题的判断依据</p><p><strong>原文定位</strong>（课件目的从句）：常由 so that（以便）、in order that、in case（以备；以防）引导，从句中通常使用情态动词</p></details><h2 id="口诀卡" tabindex="-1"><a class="header-anchor" href="#口诀卡"><span>口诀卡</span></a></h2><div class="hint-container info"><p class="hint-container-title">相关信息</p><p>本课全部口诀 主将从现：<strong>时间条件主将从现。</strong></p><p>一……就……：<strong>hardly/scarcely...when；no sooner...than；as soon as。</strong></p><p>结果从句：<strong>名前 such，形副 so；that 从句跟在后。多多少少必用 so；little&quot;小&quot;用 such、&quot;少&quot;用 so。</strong></p><p>让步倒装：<strong>让步 as 必倒装，名词提前去冠词。</strong></p></div><p>关联复习：定语从句（where 辨析）· 名词性从句（疑问词 + -ever）· 虚拟语气（as if/as though）· 时态和语态（主将从现）。</p><p>延伸阅读：状语从句 · 完整笔记 · 原始课件 PDF</p><p>有不懂的随时问你的 AI 老师——回到 ZCode 对话里直接提问即可。</p><hr>`,224),a(`p`,null,[o(m,{href:`/courses/zsb-english/l/13/`},{default:i(()=>[...l[5]||=[e(`← 第 13 课`,-1)]]),_:1}),l[8]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/`},{default:i(()=>[...l[6]||=[e(`课程目录`,-1)]]),_:1}),l[9]||=e(` · `,-1),o(m,{href:`/courses/zsb-english/l/15/`},{default:i(()=>[...l[7]||=[e(`第 15 课 →`,-1)]]),_:1})])])}var f=c(u,[[`render`,d]]);export{l as _pageData,f as default};